class SessionManager(private val tokens: TokenStore) {
    // A Channel keeps the event until the app shell collects it (a SharedFlow would drop it)
    private val _expired = Channel<Unit>(Channel.CONFLATED)
    val sessionExpired: Flow<Unit> = _expired.receiveAsFlow()

    fun onRefreshFailed() {
        tokens.clear()
        _expired.trySend(Unit)          // observed once by the app shell, which shows sign-in
    }
}

