fun buildHttpClient(config: NetworkConfig): OkHttpClient {
    val builder = OkHttpClient.Builder()
        .addInterceptor(CommonHeadersInterceptor(config.appVersion, config.locale))

    if (config.pins.isNotEmpty()) {
        val pinner = CertificatePinner.Builder().apply {
            config.pins.forEach { (host, pin) -> add(host, pin) }
        }.build()
        builder.certificatePinner(pinner)          // every request through this client is pinned
    }
    return builder.build()
}

suspend fun <T> retryWithBackoff(
    maxAttempts: Int = 4,
    baseDelayMs: Long = 500,
    maxDelayMs: Long = 8_000,
    block: suspend () -> T
): T {
    var attempt = 0
    while (true) {
        try {
            return block()
        } catch (e: CancellationException) {
            throw e
        } catch (e: IOException) {
            attempt++
            if (attempt >= maxAttempts) throw e
        }
        val ceiling = minOf(maxDelayMs, baseDelayMs shl (attempt - 1))   // 500, 1000, 2000 ...
        delay(Random.nextLong(0, ceiling + 1))         // full jitter
    }
}

fun retryAfterMillis(response: Response): Long? {
    val value = response.header("Retry-After") ?: return null
    value.toLongOrNull()?.let { return it * 1_000 }                     // seconds
    return runCatching {                                                // HTTP date
        val date = ZonedDateTime.parse(value, DateTimeFormatter.RFC_1123_DATE_TIME)
        maxOf(0, Duration.between(Instant.now(), date.toInstant()).toMillis())
    }.getOrNull()
}

